#!/usr/bin/env python3
"""A.C.E. 1.7.1 — clean-shell stabilization.

Loads the proven 1.6.5 functional runtime directly, removes the 1.7.0 overlay
injection from persisted web resources, then mounts one controlled Chat view and
one controlled Live view. Legacy UI is hidden only as a service layer for proven
controls. The visible A.C.E. brand uses the user-supplied gear logo everywhere.
"""
from pathlib import Path
import base64, hashlib, importlib.util, re, zlib

H=Path(__file__).resolve().parent
BASE=H/'ACE Base 1.6.5.py'
spec=importlib.util.spec_from_file_location('ace_base_165',str(BASE))
b165=importlib.util.module_from_spec(spec);spec.loader.exec_module(b165)
ace=b165.ace
ace.VERSION='1.7.1'
try: ace.UPDATE_STATE['current_version']='1.7.1'
except Exception: pass

LOGO_B64=''
LOGO_SHA='2aa8ed4eea55048354eb4b7eedc869d359f9c7ab09d8f0e93369b1ab8121a952'
try:
    raw=base64.b64decode(LOGO_B64);p=H/'ace171-logo.png'
    if not p.exists() or hashlib.sha256(p.read_bytes()).hexdigest()!=LOGO_SHA:p.write_bytes(raw)
except Exception:pass

def patch(path,marker,transform):
    try:
        p=Path(path);s=p.read_text(encoding='utf-8')
        if marker in s:return True
        n=transform(s)
        if n!=s:p.write_text(n,encoding='utf-8')
        return marker in n
    except Exception:return False

def trunc(s,marker,end=None):
    i=s.rfind(marker)
    if i<0:return s
    if end:
        j=s.find(end,i);return s[:j+len(end)] if j>=0 else s[:i]
    j=s.find('\n',i);return s[:j+1] if j>=0 else s[:i+len(marker)]

def idx171(s):
    if '<!--ACE165_ATTACHMENTS-->' in s:s=trunc(s,'<!--ACE165_ATTACHMENTS-->','-->')
    s=re.sub(r'app\.css\?v=[^"\']+','app.css?v=171-clean-shell',s)
    s=re.sub(r'app\.js\?v=[^"\']+','app.js?v=171-clean-shell',s)
    s=re.sub(r'Current version:\s*v?1\.(?:6\.[0-9]+|7\.0)','Current version: v1.7.1',s)
    return s+'\n<!--ACE171_CLEAN_SHELL-->\n'

CSS171=zlib.decompress(base64.b64decode('')).decode('utf-8')
JS171=zlib.decompress(base64.b64decode('')).decode('utf-8')

def css171(s):
    if '/*ACE165_ATTACHMENTS*/' in s:s=trunc(s,'/*ACE165_ATTACHMENTS*/','*/')
    return s+'\n'+CSS171+'\n'
def js171(s):
    if '// ACE165' in s:s=trunc(s,'// ACE165')
    return s+'\n'+JS171+'\n'

patch(H/'index.html','ACE171_CLEAN_SHELL',idx171)
patch(H/'app.css','ACE171_CLEAN_SHELL',css171)
patch(H/'app.js','ACE171_CLEAN_SHELL',js171)

if __name__=='__main__':ace.main()
